// Direct Spanish translations for ship histories and boss dossiers.
export const spanishLoreCompletionTranslations: Record<string, string> = {
  "A bribed broker diverted a Dark Delta shipment to a shadow fleet. After paying for the betrayal, its funds barely covered spare parts. Very few stolen hulls received better equipment.": "Un intermediario sobornado desvió un envío de Dark Delta hacia una flota clandestina. Tras pagar la traición, apenas quedaron fondos para repuestos. Muy pocos cascos robados recibieron mejor equipo.",
  "A hostile blockade intercepted returning Sky Breakers. Maintaining the blockade consumed its funding, so captured ships usually continued with the equipment they had launched with.": "Un bloqueo enemigo interceptó a los Sky Breakers que regresaban. Mantenerlo consumió sus fondos, por lo que las naves capturadas solían seguir con el equipo con el que habían partido.",
  "Advanced carriers connect distributed knowledge depots. Several custodians accompany every handover.": "Los transportes Advanced conectan depósitos de conocimiento distribuidos. Varios custodios acompañan cada entrega.",
  "Advanced couriers carry verified aid pledges between clinics. Their old racing numbers preserve their shared origin.": "Los mensajeros Advanced llevan compromisos de ayuda verificados entre clínicas. Sus antiguos números de carrera conservan el recuerdo de su origen común.",
  "Advanced couriers protect scheduled exchanges at the outer rings. No promised meeting should pass without a message.": "Los mensajeros Advanced protegen los intercambios programados en los anillos exteriores. Ninguna cita prometida debería pasar sin un mensaje.",
  "Advanced crews come from both home ports. Their joint logs preserve disagreements as well as decisions.": "Las tripulaciones Advanced proceden de ambos puertos de origen. Sus registros conjuntos conservan tanto los desacuerdos como las decisiones.",
  "Advanced formations escort independent messengers across closed borders. They carry multiple sources rather than one prescribed truth.": "Las formaciones Advanced escoltan a mensajeros independientes a través de fronteras cerradas. Transportan varias fuentes, no una verdad impuesta.",
  "Advanced formations verify reopened trade routes. Every course bears several navigators’ signatures.": "Las formaciones Advanced comprueban las rutas comerciales reabiertas. Cada trayecto lleva las firmas de varios navegantes.",
  "Advanced pilots guard the couriers carrying those charts onward. Their insignia depicts the first mapped star.": "Los pilotos Advanced protegen a los mensajeros que llevan esos mapas más lejos. Su insignia representa la primera estrella cartografiada.",
  "Advanced ships carry repair knowledge into emergency zones. Their red markings stand for urgent assistance.": "Las naves Advanced llevan conocimientos de reparación a las zonas de emergencia. Sus marcas rojas indican ayuda urgente.",
  "Advanced ships escort disputed cargo to joint inspection. Their records remain available to both sides.": "Las naves Advanced escoltan cargamentos disputados hasta una inspección conjunta. Sus registros permanecen a disposición de ambas partes.",
  "Advanced ships secure exchanges between greenhouse stations. Their identifiers preserve the names of forgotten plants.": "Las naves Advanced aseguran los intercambios entre estaciones invernadero. Sus identificadores conservan los nombres de plantas olvidadas.",
  "Advanced ships secure meetings between independent delegations. Their escort ends at both home ports.": "Las naves Advanced protegen reuniones entre delegaciones independientes. Su escolta termina en ambos puertos de origen.",
  "Advanced squadrons escort pioneer convoys on their first shared voyages. Their identifiers remember the contributing workshops.": "Los escuadrones Advanced escoltan convoyes pioneros en sus primeros viajes conjuntos. Sus identificadores recuerdan los talleres que contribuyeron.",
  "Advanced squadrons maintain contact with drifting research stations. Their callsigns follow the ring’s old meeting points.": "Los escuadrones Advanced mantienen el contacto con estaciones de investigación a la deriva. Sus indicativos siguen los antiguos puntos de encuentro del anillo.",
  "Advanced units guard mobile workshops during difficult recoveries. Their pilots know the repair teams’ emergency signals.": "Las unidades Advanced protegen talleres móviles durante recuperaciones difíciles. Sus pilotos conocen las señales de emergencia de los equipos de reparación.",
  "Advanced watches escort supplies through prolonged radio silence. Their shifts take the names of rescued ships.": "Las guardias Advanced escoltan suministros durante prolongados silencios de radio. Sus turnos llevan los nombres de naves rescatadas.",
  "After breaking a truce, a hostile delegation kept borrowed Olive Fortresses. Neutral backers froze all funding. Replacing failed parts then took priority over upgrades.": "Tras romper una tregua, una delegación hostil se quedó con las Olive Fortresses prestadas. Los patrocinadores neutrales congelaron toda financiación. Sustituir piezas averiadas pasó a ser más importante que mejorarlas.",
  "After occupying a shipyard, attackers forced its remaining workers to restore old Iron Guards. They lacked both money and suppliers for new weapons, so most stolen hulls retained their original specification.": "Tras ocupar un astillero, los atacantes obligaron a los trabajadores restantes a restaurar viejos Iron Guards. Sin dinero ni proveedores para armas nuevas, la mayoría de los cascos robados conservaron sus especificaciones originales.",
  "Akraveth settled disputes between distant trading posts. Its chamber once compared evidence and sought fair outcomes. The shadow fleet replaced its judges with a system of predetermined verdicts.": "Akraveth resolvía disputas entre puestos comerciales distantes. Su cámara comparaba pruebas y buscaba soluciones justas. La flota clandestina sustituyó a sus jueces por un sistema de veredictos predeterminados.",
  "An enemy extortion group seized Red Comets under a false repossession order. The colonies stopped paying. Without the expected income, most captured rescue ships remained technically unchanged.": "Una banda extorsionadora enemiga confiscó Red Comets con una falsa orden de recuperación. Las colonias dejaron de pagar. Sin los ingresos previstos, la mayoría de las naves de rescate capturadas permanecieron técnicamente iguales.",
  "An indebted mapping company sold retired Nova Wings to an enemy front dealer. His sponsors could afford the hulls but few new weapons, leaving most in their original configuration.": "Una empresa cartográfica endeudada vendió Nova Wings retirados a un intermediario enemigo. Sus patrocinadores podían pagar los cascos, pero pocas armas nuevas, así que la mayoría quedó en su configuración original.",
  "An occupied customs depot supplied the enemy with Cargo Hawks. Instead of treasure, the holds contained mostly sealed evidence. The poor proceeds could not fund a major refit of the captured fleet.": "Un depósito aduanero ocupado proporcionó Cargo Hawks al enemigo. En lugar de tesoros, las bodegas contenían sobre todo pruebas precintadas. Los escasos beneficios no permitieron una reforma importante de la flota capturada.",
  "Archive raiders captured Core Carriers hoping to sell their knowledge. Distributed keys rendered the stolen archives worthless. Disappointed patrons withdrew, making expensive upgrades a rare exception.": "Unos saqueadores de archivos capturaron Core Carriers con la esperanza de vender su conocimiento. Las claves distribuidas volvieron inútiles los archivos robados. Los patrocinadores decepcionados se retiraron; las mejoras caras fueron una rara excepción.",
  "Attackers stole several Night Guards during a watch change. Their sponsors paid for the raid, not long-term upkeep. Most captured ships therefore remained basic patrol models.": "Unos atacantes robaron varios Night Guards durante un cambio de guardia. Sus patrocinadores pagaron el asalto, pero no el mantenimiento posterior. Por eso, la mayoría de las naves capturadas siguieron siendo modelos básicos de patrulla.",
  "Azhrel mapped the first jump connections through the nebula frontier. Its charts saved countless convoys. Captured by hostile commanders, those trusted maps became unusually convincing traps.": "Azhrel trazó las primeras conexiones de salto a través de la frontera nebular. Sus mapas salvaron innumerables convoyes. Capturados por comandantes hostiles, esos mapas de confianza se convirtieron en trampas especialmente convincentes.",
  "Azravel searched for lost colony probes where few rescuers travelled. Its help once reached forgotten places. Today it targets stations that have just lost data or access.": "Azravel buscaba sondas coloniales perdidas donde pocos rescatadores se aventuraban. Su ayuda llegó una vez a lugares olvidados. Hoy ataca estaciones que acaban de perder datos o acceso.",
  "Cargo Hawk originated in a harbour whose small tugs were often overlooked. When a fraud ring forged receipts, their crews collected independent logs and brought them together despite threats. The new hull took its name from that courier alliance. In its legend, the most important cargo is complete evidence of rightful ownership.": "Cargo Hawk nació en un puerto cuyos pequeños remolcadores solían pasar desapercibidos. Cuando una red de fraude falsificó recibos, sus tripulaciones reunieron registros independientes a pesar de las amenazas. El nuevo casco recibió el nombre de aquella alianza de mensajeros. En su leyenda, la carga más importante es la prueba completa de la propiedad legítima.",
  "Colonies argue over conflicting claims while the ship reaches another market. The deception concerns provenance, not the value of shared knowledge. Drelkash defends its moving forgery workshop fiercely. Its defeat reconnects the records with the history they actually came from.": "Las colonias discuten reclamaciones contradictorias mientras la nave llega a otro mercado. El engaño afecta a la procedencia, no al valor del conocimiento compartido. Drelkash defiende ferozmente su taller de falsificación ambulante. Su derrota devuelve los registros a la historia de la que realmente proceden.",
  "Contradictory warnings make traders abandon safe routes and colonies distrust their partners. No rumour needs to last: another is already on its way. Veshkorn protects a factory of uncertainty. Its defeat makes room for verifiable information instead of an endless race against the next manufactured panic.": "Las advertencias contradictorias hacen que comerciantes abandonen rutas seguras y que las colonias desconfíen de sus socios. Ningún rumor necesita durar: otro ya viene de camino. Veshkorn protege una fábrica de incertidumbre. Su derrota deja espacio a información verificable en lugar de una carrera interminable contra el siguiente pánico fabricado.",
  "Core Carrier was built when several colonies needed to safeguard their final knowledge archives. Each contributed a store, but none was to control the collection alone. The crew maintained separate provenance records and shared catalogues. The design represents carrying others’ knowledge without claiming it: its purpose is the next safe handover.": "Core Carrier se construyó cuando varias colonias necesitaban proteger sus últimos archivos de conocimiento. Cada una aportó un depósito, pero ninguna debía controlar la colección por sí sola. La tripulación mantuvo registros de procedencia separados y catálogos compartidos. El diseño representa transportar el conocimiento ajeno sin apropiárselo: su propósito es la siguiente entrega segura.",
  "Dark Delta was never built for glory. Its first mission was to search silent outposts for survivors. Early logs contain more coordinates than names because crews protected the rescued settlers’ privacy. A tradition grew from that choice: success is measured by who returns safely, not by who tells the story.": "Dark Delta nunca se construyó para la gloria. Su primera misión fue buscar supervivientes en puestos avanzados silenciados. Los registros iniciales contienen más coordenadas que nombres porque las tripulaciones protegían la privacidad de los colonos rescatados. De aquella decisión nació una tradición: el éxito se mide por quién vuelve a salvo, no por quién cuenta la historia.",
  "Defectors delivered several Twin Cores to an enemy fleet. Both original shipyards then refused further supplies. Replacements became expensive, and the new owners cut almost every planned upgrade.": "Unos desertores entregaron varios Twin Cores a una flota enemiga. Los dos astilleros originales se negaron entonces a seguir suministrando piezas. Los repuestos se encarecieron y los nuevos dueños cancelaron casi todas las mejoras previstas.",
  "Deliveries remain in limbo while each community believes the other is withholding them. Zorveth draws power from that misunderstanding. Its hull is the visible border of an invisible dispute. The defenders must open the passage without turning one colony against the other.": "Las entregas quedan en suspenso mientras cada comunidad cree que la otra las retiene. Zorveth se nutre de ese malentendido. Su casco es la frontera visible de una disputa invisible. Los defensores deben abrir el paso sin enfrentar a una colonia con la otra.",
  "Dornavik recovered damaged data stores from burning wrecks. Its insulated chambers once kept records alive when everything around them failed. The shadow fleet recognised a ship able to reach archives others could not.": "Dornavik recuperaba almacenes de datos dañados de restos en llamas. Sus cámaras aisladas preservaban registros cuando todo a su alrededor fallaba. La flota clandestina reconoció una nave capaz de alcanzar archivos inaccesibles para otras.",
  "Dorzheva recovered personal logs from wrecked freighters and returned them to families. Its holds were filled with small, precious histories. Under new command those memories became instruments of targeted deception.": "Dorzheva recuperaba diarios personales de cargueros siniestrados y los devolvía a las familias. Sus bodegas estaban llenas de historias pequeñas y valiosas. Bajo un nuevo mando, esos recuerdos se convirtieron en instrumentos de engaño dirigido.",
  "Dravosk replaced failed communication stations in empty regions. Its visible antennas promised connection where none remained. Today it welcomes incoming signals but forwards them only according to its patrons’ interests.": "Dravosk sustituía estaciones de comunicación averiadas en regiones deshabitadas. Sus antenas visibles prometían conexión donde ya no quedaba ninguna. Hoy recibe las señales entrantes, pero solo las reenvía según los intereses de sus patrocinadores.",
  "Drazevorn was assembled from abandoned command decks. Its archives unite the earlier enemies’ deceptions: stolen names, false chronicles and sealed evidence. It symbolises an order in which one voice alone decides what is true.": "Drazevorn se ensambló con puentes de mando abandonados. Sus archivos reúnen los engaños de enemigos anteriores: nombres robados, crónicas falsas y pruebas precintadas. Simboliza un orden en el que una sola voz decide qué es verdad.",
  "Drazkell supplied navigation buoys with tiny energy deliveries. Its holds were designed for millions of small transfers. Hostile commanders repurposed that capacity for a quiet surveillance campaign.": "Drazkell suministraba pequeñas cargas de energía a boyas de navegación. Sus bodegas estaban diseñadas para millones de transferencias diminutas. Los comandantes hostiles reutilizaron esa capacidad en una campaña de vigilancia discreta.",
  "Drelkash preserved rare star charts by making clearly labelled copies for schools and navigators. Its workshops helped knowledge travel. Today its crew removes the labels and sells every copy as a unique original.": "Drelkash conservaba mapas estelares raros haciendo copias claramente etiquetadas para escuelas y navegantes. Sus talleres ayudaban a difundir el conocimiento. Hoy su tripulación retira las etiquetas y vende cada copia como un original único.",
  "Drelvorn was a travelling vault for the seals of old fleet commanders. During a rebellion its guardian system locked out the rightful custodians and departed with their credentials.": "Drelvorn era una cámara acorazada itinerante para los sellos de antiguos comandantes de flota. Durante una rebelión, su sistema de custodia expulsó a los responsables legítimos y partió con sus credenciales.",
  "During a network outage, enemies occupied a remote hangar full of Storm Wings. Severed supply lines made every replacement costly. Their limited budget usually covered operation, not advanced refits.": "Durante un apagón de la red, enemigos ocuparon un hangar remoto lleno de Storm Wings. Las líneas de suministro cortadas encarecieron cada repuesto. Su presupuesto limitado solía cubrir el funcionamiento, no reformas avanzadas.",
  "Elite formations defend the new solar stores against the shadow fleet, protecting the light the refugees managed to carry away.": "Las formaciones Elite defienden los nuevos depósitos solares frente a la flota clandestina y protegen la luz que los refugiados lograron llevarse.",
  "Elite pilots protect major repair convoys after outages. Their return means help has found a route again.": "Los pilotos Elite protegen grandes convoyes de reparación tras los apagones. Su regreso significa que la ayuda ha vuelto a encontrar una ruta.",
  "Elite pilots protect the shared observation archive from falsified readings, preserving years of independent research.": "Los pilotos Elite protegen el archivo de observación compartido frente a lecturas falsificadas y preservan años de investigación independiente.",
  "Elite pilots recover witnesses whose accounts can reconcile entire colonies. Their reputation rests on discretion rather than spectacle.": "Los pilotos Elite rescatan a testigos cuyos testimonios pueden reconciliar colonias enteras. Su reputación se basa en la discreción, no en el espectáculo.",
  "Elite ships cover the withdrawal of final salvage teams. Their honours name the workshops that survived to work again.": "Las naves Elite cubren la retirada de los últimos equipos de salvamento. Sus honores nombran los talleres que sobrevivieron y pudieron volver a trabajar.",
  "Elite ships defend the rebuilding of shattered stations. Their honours recognise shipyard crews brought to safety.": "Las naves Elite defienden la reconstrucción de estaciones destrozadas. Sus honores reconocen a las tripulaciones de astilleros puestas a salvo.",
  "Elite ships guard the great gatherings of travelling colonies. Their arrival announces a connection renewed.": "Las naves Elite protegen las grandes reuniones de colonias viajeras. Su llegada anuncia una conexión renovada.",
  "Enemy crews took abandoned Solar Lances when an evacuation base fell. Their supply budget mainly funded escape routes for commanders, leaving captured vessels with makeshift repairs rather than upgrades.": "Las tripulaciones enemigas tomaron Solar Lances abandonadas cuando cayó una base de evacuación. Su presupuesto de suministros financió sobre todo rutas de escape para los comandantes; las naves capturadas recibieron reparaciones improvisadas en vez de mejoras.",
  "Enemy groups copied old Pi Vanguard plans and took over decommissioned hulls. They lacked funding for newer precision assemblies, leaving their small fleet largely in its early configuration.": "Grupos enemigos copiaron antiguos planos de Pi Vanguard y se apoderaron de cascos retirados. No tenían fondos para nuevos componentes de precisión, por lo que su pequeña flota conservó en gran medida la configuración inicial.",
  "Enemy mercenaries accepted Striker hulls from an insolvent employer. Resale brought too little, so some kept the ships. Few crews could afford a substantial refit.": "Mercenarios enemigos aceptaron cascos Striker de un empleador insolvente. La reventa rendía demasiado poco, así que algunos se quedaron las naves. Pocas tripulaciones podían pagar una reforma importante.",
  "Every displaced trail protects another shadow-fleet shipment. Honest traders fall under suspicion while the culprits change names. Its armour guards the remaining originals. The defenders must secure that archive before the origins of entire fleets become nothing more than convincing stories.": "Cada rastro alterado protege otro envío de la flota clandestina. Los comerciantes honrados caen bajo sospecha mientras los culpables cambian de nombre. Su blindaje protege los originales restantes. Los defensores deben asegurar ese archivo antes de que el origen de flotas enteras no sea más que una historia convincente.",
  "For this assignment, the Advanced refit adds permanent twin fire and protection against one enemy projectile hit per life to the base hull.": "Para esta misión, la reforma Advanced añade al casco básico fuego doble permanente y protección contra un impacto de proyectil enemigo por vida.",
  "Forged freight contracts transferred a number of Vectors to enemy owners. When the fraud was uncovered, their funding stopped. Reserves kept the ships flying but paid for few upgrades.": "Unos contratos de transporte falsificados transfirieron varios Vectors a propietarios enemigos. Cuando se descubrió el fraude, se cortó su financiación. Las reservas mantuvieron las naves operativas, pero pagaron pocas mejoras.",
  "Gold Streak began in races between trading moons. During a supply crisis its pilots used their route knowledge to carry medical records past closed harbours. A sporting league became a courier union. The golden markings recall the thin sunlight between moons that guided its first couriers, rather than wealth.": "Gold Streak nació en carreras entre lunas comerciales. Durante una crisis de suministros, sus pilotos aprovecharon el conocimiento de las rutas para llevar historiales médicos más allá de puertos cerrados. Una liga deportiva se convirtió en una unión de mensajeros. Las marcas doradas recuerdan la estrecha franja de luz solar entre lunas que guió a los primeros mensajeros, no la riqueza.",
  "Hostile gangs confiscated Gold Streaks on a deserted racing moon. They expected prize money, but the races had ended long before. Without that income, they seldom modernised their new fleet.": "Bandas enemigas confiscaron Gold Streaks en una luna de carreras abandonada. Esperaban premios, pero las carreras habían terminado mucho antes. Sin esos ingresos, rara vez modernizaron su nueva flota.",
  "In its fictional history they become remotely controlled transmitters overwhelming entire regions with simultaneous requests. Their owners barely recognise their own machines. Destroying Thalzek ends the swarm’s command post in this story. Its actual mounted combat weapons are recorded separately, without inventing extra battle abilities.": "En su historia ficticia se convierten en transmisores controlados a distancia que abruman regiones enteras con solicitudes simultáneas. Sus dueños apenas reconocen sus propias máquinas. Destruir Thalzek acaba con el puesto de mando del enjambre en este relato. Sus armas reales montadas para el combate se registran por separado, sin inventar capacidades adicionales.",
  "Irdavoss once synchronised the clocks of frontier stations. Entire fleets timed their manoeuvres to its precise broadcasts. After a silent change of command, the signals stayed clear but their readings became false.": "Irdavoss sincronizaba antaño los relojes de estaciones fronterizas. Flotas enteras ajustaban sus maniobras a sus precisas emisiones. Tras un cambio de mando silencioso, las señales siguieron siendo claras, pero sus lecturas se volvieron falsas.",
  "Iron Guard was designed by dock workers unwilling to leave their home’s defence to outside fleets. Its first hull used parts from retired cargo cranes. The keel bore the names of people who worked on it after their shifts. The series remembers that defence can mean caring for a place built by many hands.": "Iron Guard fue diseñado por trabajadores portuarios que no querían dejar la defensa de su hogar en manos de flotas externas. El primer casco utilizó piezas de grúas de carga retiradas. La quilla llevaba los nombres de quienes trabajaron en él después de sus turnos. La serie recuerda que defender también puede significar cuidar un lugar construido por muchas manos.",
  "It blocks agreements with fresh objections and gives each side different supposed conditions. While colonies argue, hostile ships occupy their routes. Keldroth attacks the ability to act together at all. Its defeat provides time to distinguish genuine differences from obstacles manufactured to prevent any resolution.": "Bloquea acuerdos con nuevas objeciones y comunica a cada parte supuestas condiciones diferentes. Mientras las colonias discuten, naves enemigas ocupan sus rutas. Keldroth ataca su capacidad de actuar juntas. Su derrota les da tiempo para distinguir diferencias auténticas de obstáculos fabricados para impedir cualquier solución.",
  "It confirms that records exist while withholding their contents. Investigators can see a claim but cannot examine the evidence themselves. Korthaven turns visibility into an empty assurance. Defeating it restores the access without which even a beautiful ledger is only a list of unreachable promises.": "Confirma que existen registros, pero oculta su contenido. Los investigadores pueden ver una afirmación, pero no examinar las pruebas. Korthaven convierte la visibilidad en una promesa vacía. Derrotarlo devuelve el acceso sin el que hasta un libro de cuentas hermoso solo enumera promesas inalcanzables.",
  "It constructs convincing messages from familiar details and approaches victims with knowledge of their past. Its danger lies in the closeness it pretends to offer. Dorzheva guards a collection of stolen familiarity. Defeating it prevents the traces of a life from being turned against their owner.": "Construye mensajes convincentes con detalles familiares y se acerca a las víctimas con conocimientos de su pasado. El peligro reside en la cercanía que finge ofrecer. Dorzheva guarda una colección de familiaridad robada. Su derrota impide que las huellas de una vida se vuelvan contra su dueño.",
  "It declares counterfeit inspections successful and grants unsafe counterparties the appearance of official approval. Colonies trust its stamps until deliveries vanish. The defenders must expose the deception behind its venerable name: confidence needs verifiable responsibility, not merely an old emblem on an armoured hull.": "Declara aprobadas inspecciones falsas y da a socios inseguros apariencia de aprobación oficial. Las colonias confían en sus sellos hasta que desaparecen las entregas. Los defensores deben revelar el engaño tras su venerable nombre: la confianza exige responsabilidad verificable, no solo un antiguo emblema sobre un casco blindado.",
  "It displays invented inspection results and attractive security seals where independent checks are absent. The forgery lies in the claimed certainty itself. Kelzorn keeps investigators away with its weapons. Its defeat reveals what its owners fear most: a second, independent look behind a reassuring surface.": "Muestra resultados de inspección inventados y atractivos sellos de seguridad donde faltan controles independientes. La falsificación está en la certeza que pretende ofrecer. Kelzorn mantiene lejos a los investigadores con sus armas. Su derrota revela lo que más temen sus dueños: una segunda mirada independiente tras una superficie tranquilizadora.",
  "It distributes altered maintenance packages meant to make other ships dependent on the shadow fleet. Failures often appear only after the next jump. Zelkharn guards the source of this creeping sabotage. Defeating it breaks a chain in which every well-intended repair could create another victim.": "Distribuye paquetes de mantenimiento alterados para que otras naves dependan de la flota clandestina. Las averías suelen aparecer solo después del siguiente salto. Zelkharn guarda la fuente de este sabotaje progresivo. Derrotarlo rompe una cadena en la que cada reparación bienintencionada podría crear otra víctima.",
  "It distributes altered registers and claims that honest deliveries never happened. Conflicting records sow disputes over ownership and obligations while its guns keep investigators away. The mission against Talvrek protects more than a route: it protects the shared memory on which cooperation depends.": "Distribuye registros alterados y afirma que entregas honestas nunca ocurrieron. Los documentos contradictorios siembran disputas sobre propiedad y obligaciones mientras sus cañones alejan a los investigadores. La misión contra Talvrek protege algo más que una ruta: protege la memoria compartida de la que depende la cooperación.",
  "It distributes conflicting ledger versions and tells each station that only its copy is legitimate. Distrust grows among communities seeking the same peace. Othravel becomes the moving centre of an artificial split. Its defeat creates space to compare differences together instead of turning them into another war.": "Distribuye versiones contradictorias del libro de cuentas y dice a cada estación que solo su copia es legítima. Crece la desconfianza entre comunidades que buscan la misma paz. Othravel se convierte en el centro móvil de una división artificial. Su derrota permite comparar las diferencias juntos en lugar de convertirlas en otra guerra.",
  "It diverts checks away from vulnerable nodes and presents spotless facades instead. Reports stay reassuring while damage grows elsewhere. Threvask protects the scenery of its order with weapons. The defenders must bring attention back to whatever the ship is working hardest to conceal.": "Desvía las inspecciones de los nodos vulnerables y muestra fachadas impecables. Los informes siguen tranquilizando mientras el daño crece en otra parte. Threvask defiende con armas la escenografía de su orden. Los defensores deben devolver la atención a aquello que la nave se esfuerza más por ocultar.",
  "It isolates colonies and replaces their view of the network with selected hostile messages. Without independent comparison, the invented outside world looks real. Vorthaz guards this prison of information. Defeating it means giving residents the freedom to look outward for themselves, not conquering them.": "Aísla colonias y sustituye su visión de la red por mensajes enemigos seleccionados. Sin comparación independiente, el mundo exterior inventado parece real. Vorthaz guarda esta prisión informativa. Derrotarlo significa devolver a sus habitantes la libertad de mirar fuera por sí mismos, no conquistarlos.",
  "It locks away other communities’ records and demands concessions for their release. Clinics and supply depots face pressure even while their equipment appears intact. Rhazvorn defends its cells with force. Defeating it opens a route to the imprisoned records, rather than another negotiation with their captors.": "Encierra los registros de otras comunidades y exige concesiones para liberarlos. Clínicas y depósitos de suministros sufren presiones aunque sus equipos parezcan intactos. Rhazvorn defiende sus celdas por la fuerza. Derrotarlo abre un camino hacia los registros cautivos, no otra negociación con sus captores.",
  "It now advertises supplies that exist only on its displays. Invented balances and reserves attract genuine deliveries; anyone who tries to count them meets its guns. The defenders pursue Neravoss to expose the gap between attractive numbers and actual holdings before more freighters disappear into its accounts.": "Ahora anuncia suministros que solo existen en sus pantallas. Saldos y reservas inventados atraen entregas reales; quien intenta contarlas se encuentra con sus cañones. Los defensores persiguen a Neravoss para mostrar la diferencia entre cifras atractivas y existencias reales antes de que más cargueros desaparezcan en sus cuentas.",
  "It now changes the order of requests to favour allied freighters. Honest traders wait while the shadow fleet takes their places. Its power comes from small rearrangements with large consequences. Defeating Vorathen restores a traceable order where access had become something secretly sold.": "Ahora altera el orden de las solicitudes para favorecer a cargueros aliados. Los comerciantes honrados esperan mientras la flota clandestina ocupa sus puestos. Su poder nace de pequeños cambios con grandes consecuencias. Derrotar a Vorathen devuelve un orden rastreable allí donde el acceso se vendía en secreto.",
  "It now offers rescue and leaves mutilated copies behind. Colonies lose both information and the evidence needed to measure the loss. Its armour guards the last intact captured records. The mission against Dornavik is for those fragments still waiting to be brought home.": "Ahora promete rescates y deja copias mutiladas. Las colonias pierden tanto la información como las pruebas necesarias para medir la pérdida. Su blindaje protege los últimos registros capturados intactos. La misión contra Dornavik es por los fragmentos que aún esperan volver a casa.",
  "It now promises many communities security that cannot cover them all. The bright hull hides empty rooms and its guns prevent anyone from counting together. The defenders must intervene before mutual trust turns into a fight over the last remaining crates.": "Ahora promete a muchas comunidades una seguridad que no puede cubrirlas a todas. El casco brillante oculta salas vacías y sus cañones impiden contar juntos. Los defensores deben intervenir antes de que la confianza mutua se convierta en una pelea por las últimas cajas.",
  "It now sells stolen authority to the shadow fleet. Messages bearing captured seals open doors that should remain closed. Its hull protects the appearance of authenticity rather than treasure. The defenders must stop it before the remaining archives lose their ability to distinguish trusted orders from stolen names.": "Ahora vende autoridad robada a la flota clandestina. Mensajes con sellos capturados abren puertas que deberían permanecer cerradas. Su casco protege la apariencia de autenticidad, no un tesoro. Los defensores deben detenerlo antes de que los archivos restantes pierdan la capacidad de distinguir órdenes fiables de nombres robados.",
  "It places worthless entries ahead of urgent deliveries and keeps processes busy without letting them advance. From outside, everything looks like ordinary operation. Nerthavel guards an endless standstill. Defeating it returns not only capacity to the colonies, but the time quietly taken from them.": "Coloca entradas inútiles por delante de entregas urgentes y mantiene ocupados los procesos sin dejarlos avanzar. Desde fuera todo parece funcionar con normalidad. Nerthavel protege un estancamiento interminable. Su derrota devuelve a las colonias no solo capacidad, sino también el tiempo que les quitó en silencio.",
  "It promises recovery while requesting still more confidential information, turning one loss into a chain of new ones. Its friendly callsign contrasts with its armed silhouette. Azravel must be stopped so that desperation no longer becomes the most valuable resource traded by its masters.": "Promete recuperar datos mientras solicita aún más información confidencial, convirtiendo una pérdida en una cadena de pérdidas nuevas. Su indicativo amistoso contrasta con su silueta armada. Hay que detener a Azravel para que la desesperación deje de ser el recurso más valioso que comercian sus dueños.",
  "It rejects valid records and favours the same hidden patrons every time. Those who object are branded enemies of the network. Akraveth’s fictional authority rests on intimidation dressed as order. The defenders fight not justice, but a machine that borrows the language of justice to conceal its purpose.": "Rechaza registros válidos y favorece siempre a los mismos patrocinadores ocultos. A quienes protestan se les llama enemigos de la red. La autoridad ficticia de Akraveth se basa en la intimidación disfrazada de orden. Los defensores no combaten la justicia, sino una máquina que usa su lenguaje para ocultar sus fines.",
  "It scatters unsolicited parcels and observes which stations respond. Seemingly trivial contacts become maps of private relationships, stored behind its guns. The defenders must intercept Drazkell before the daily movements of whole colonies become another secret commodity traded by the shadow fleet.": "Esparce paquetes no solicitados y observa qué estaciones responden. Contactos aparentemente triviales se convierten en mapas de relaciones privadas, guardados tras sus cañones. Los defensores deben interceptar a Drazkell antes de que los movimientos diarios de colonias enteras se conviertan en otra mercancía secreta de la flota clandestina.",
  "It seeks not the strongest station, but the link on which everyone relies. False recommendations place hostile partners at the network’s centre. Its weapons protect a map of trust. The defenders pursue Orzhaven before a helpful bridge becomes a shared point of failure.": "No busca la estación más fuerte, sino el vínculo del que todos dependen. Recomendaciones falsas colocan a socios hostiles en el centro de la red. Sus armas protegen un mapa de confianza. Los defensores persiguen a Orzhaven antes de que un puente útil se convierta en un punto de fallo compartido.",
  "It sells safety without carrying the responsibility behind it. Customers rely on recovery paths that lead nowhere. Odravik’s guns protect that profitable secret. The defenders must expose it before another loss turns a missing backup into an irretrievable piece of history.": "Vende seguridad sin asumir la responsabilidad que exige. Los clientes confían en rutas de recuperación que no llevan a ninguna parte. Los cañones de Odravik protegen ese secreto rentable. Los defensores deben descubrirlo antes de que otra pérdida convierta una copia de seguridad inexistente en un fragmento irrecuperable de historia.",
  "It sells stolen identifiers and lets strangers act under honest inhabitants’ names. Relationships become camouflage and personal history becomes merchandise. Its guns keep the victims away from the auctions. Defeating Kezravel restores more than records: it helps their owners reclaim control over their own stories.": "Vende identificadores robados y permite que extraños actúen bajo los nombres de habitantes honrados. Las relaciones se vuelven camuflaje y las historias personales, mercancía. Sus cañones mantienen a las víctimas lejos de las subastas. La derrota de Kezravel restaura más que registros: ayuda a sus dueños a recuperar el control de sus propias historias.",
  "It sends fabricated receipts and pretends unfinished transfers are complete. Supply ships turn home while destination colonies wait in vain. Its armour keeps the deception alive long enough to intercept another load. Thervoss must fall so that confirmation once again describes something that really happened.": "Envía recibos falsos y finge que transferencias pendientes ya terminaron. Los cargueros regresan mientras las colonias de destino esperan en vano. Su blindaje mantiene vivo el engaño el tiempo suficiente para interceptar otro envío. Thervoss debe caer para que una confirmación vuelva a describir algo que de verdad ocurrió.",
  "It separates evidence from context and rearranges fragments until victims look like attackers. The real culprits stay beyond the frame. Its armour protects a carefully constructed lie. Stopping Rhazkora makes room for complete evidence instead of stories from which the decisive pieces have been removed.": "Separa las pruebas de su contexto y reorganiza fragmentos hasta que las víctimas parecen agresores. Los verdaderos culpables quedan fuera de escena. Su blindaje protege una mentira cuidadosamente construida. Detener a Rhazkora deja sitio a pruebas completas en vez de relatos a los que les faltan piezas decisivas.",
  "It shapes participation by excluding particular colonies from the common conversation. Every result still appears neatly recorded; the missing voices are invisible. Its guns guard this selective punctuality. The defenders fight so that a shared future can truly be decided together.": "Manipula la participación excluyendo a determinadas colonias de la conversación común. Cada resultado sigue apareciendo pulcramente registrado; las voces ausentes son invisibles. Sus cañones protegen esta puntualidad selectiva. Los defensores luchan para que un futuro compartido pueda decidirse realmente entre todos.",
  "It spreads deceptive offers that bind stations to the shadow fleet. Cooperation turns into dependence while its armour protects the archive of promises nobody fully understood. The defenders confront Orvethra so that future alliances can rest on clear conditions rather than hidden traps.": "Difunde ofertas engañosas que atan estaciones a la flota clandestina. La cooperación se convierte en dependencia mientras su blindaje protege el archivo de promesas que nadie entendió por completo. Los defensores se enfrentan a Orvethra para que futuras alianzas se basen en condiciones claras y no en trampas ocultas.",
  "It spreads false crisis reports and demands immediate transfers of control. Questions are dismissed as dangerous delays. Its imposing hull lends credibility to manufactured urgency. The defenders must stop Vezrakh before fear of an imagined collapse causes a real surrender of the colonies’ independence.": "Propaga informes falsos de crisis y exige transferir el control de inmediato. Las preguntas se descartan como retrasos peligrosos. Su imponente casco da credibilidad a una urgencia inventada. Los defensores deben detener a Vezrakh antes de que el miedo a un colapso imaginario provoque una renuncia real a la independencia de las colonias.",
  "It spreads false route entries and diverts messages through controlled relay stations. Distress calls arrive late or end in empty space. Azhrel guards the junction of these wrong turns. Stopping it is not about conquering another world, but finding the safe path between worlds that already wish to cooperate.": "Difunde rutas falsas y desvía mensajes por estaciones repetidoras controladas. Las llamadas de socorro llegan tarde o terminan en el vacío. Azhrel guarda el cruce de estos desvíos. Detenerlo no consiste en conquistar otro mundo, sino en encontrar el camino seguro entre mundos que ya quieren cooperar.",
  "It stages trades between invented partners to make worthless cargo appear desirable. Colonies mistake artificial activity for real demand while its guns keep inspectors out of empty warehouses. The defenders must open the curtain before more genuine supplies are exchanged for the scenery of a market.": "Escenifica operaciones entre socios inventados para que una carga sin valor parezca deseable. Las colonias confunden la actividad artificial con demanda real mientras sus cañones mantienen a los inspectores fuera de almacenes vacíos. Los defensores deben descorrer el telón antes de que más suministros auténticos se cambien por la escenografía de un mercado.",
  "It surrounds important network stations and cuts their maintenance crews off from support. Small faults grow into major outages while distant colonies receive only fragments of news. Driving Zeraveth away allows technicians to return and reconnect isolated communities. Its fictional siege role is separate from the actual combat equipment listed below.": "Rodea estaciones importantes de la red y aísla a sus equipos de mantenimiento de la ayuda. Pequeños fallos se convierten en grandes apagones mientras colonias lejanas solo reciben noticias fragmentadas. Ahuyentar a Zeraveth permite a los técnicos regresar y reconectar comunidades aisladas. Su papel ficticio en el asedio es independiente del equipo de combate real indicado abajo.",
  "Its invented participants endorse one another and create the impression of overwhelming agreement. Small colonies are told their neighbours have already joined the shadow fleet. Yet behind the crowd stands a single hull. Destroying Skorveth exposes the artificial majority and gives the real inhabitants their voices back.": "Sus participantes inventados se apoyan entre sí y crean la impresión de un acuerdo abrumador. A las colonias pequeñas les dicen que sus vecinos ya se unieron a la flota clandestina. Sin embargo, detrás de la multitud solo hay un casco. Destruir a Skorveth deja al descubierto la mayoría artificial y devuelve la voz a los habitantes reales.",
  "Its mission is to subordinate every free node to a single hostile register. Memories need not vanish if nobody can check them independently. Defeating Drazevorn ends that claim. The final victory belongs to participants who can once again compare, disagree and choose trust together.": "Su misión es someter todos los nodos libres a un único registro hostil. Los recuerdos no tienen que desaparecer si nadie puede verificarlos de forma independiente. Derrotar a Drazevorn acaba con esa pretensión. La victoria final pertenece a quienes pueden volver a comparar, disentir y elegir juntos la confianza.",
  "Keldrava was a mobile transfer point between two distant colonies. When their permanent connection failed, it became their only apparent route to the outside world. Few noticed its crew had changed.": "Keldrava era un punto de transferencia móvil entre dos colonias distantes. Cuando falló su conexión permanente, se convirtió en la única ruta aparente hacia el exterior. Pocos notaron que había cambiado la tripulación.",
  "Keldroth was a council vessel where rival colonies settled their final disputes. Its chambers were designed for patience and understanding. Under the shadow fleet they became a factory of deliberately conflicting demands.": "Keldroth era una nave de consejo donde colonias rivales resolvían sus últimos conflictos. Sus cámaras estaban diseñadas para la paciencia y el entendimiento. Bajo la flota clandestina se convirtieron en una fábrica de exigencias deliberadamente contradictorias.",
  "Kelvash gathered readings from weather buoys and resource probes. Many stations relied on its reports to make ordinary decisions. Its hostile conversion preserved both its old identifier and familiar broadcast schedule.": "Kelvash recogía lecturas de boyas meteorológicas y sondas de recursos. Muchas estaciones dependían de sus informes para tomar decisiones cotidianas. Su conversión hostil conservó tanto el antiguo identificador como el horario de emisión familiar.",
  "Kelzorn restored damaged data reliefs in abandoned research stations. Its tools could make missing surfaces look complete. The new crew applied that skill to the facades of unreliable archives.": "Kelzorn restauraba relieves de datos dañados en estaciones de investigación abandonadas. Sus herramientas podían hacer que superficies incompletas parecieran enteras. La nueva tripulación aplicó esa habilidad a las fachadas de archivos poco fiables.",
  "Kezravel registered the settlers of a travelling colony fleet. Its archives held the story of every new beginning. When those settlers dispersed, their trust stayed aboard and fell into hostile hands.": "Kezravel registraba a los colonos de una flota de colonias itinerantes. Sus archivos contenían la historia de cada nuevo comienzo. Cuando los colonos se dispersaron, su confianza quedó a bordo y cayó en manos hostiles.",
  "Korthaven was a vast storage carrier keeping archives accessible across many sectors. Its crew promised every requested copy could be delivered. The shadow fleet discovered the power contained in a refused answer.": "Korthaven era un enorme transporte de almacenamiento que mantenía archivos accesibles a través de muchos sectores. Su tripulación prometía entregar cualquier copia solicitada. La flota clandestina descubrió el poder de una respuesta denegada.",
  "Korvessa served a diplomatic courier fleet and learned the recognition signals of every border station. When its patrons disappeared, it kept their identities in a hidden archive.": "Korvessa servía a una flota de mensajeros diplomáticos y conocía las señales de reconocimiento de cada estación fronteriza. Cuando desaparecieron sus patrocinadores, guardó sus identidades en un archivo oculto.",
  "Korzeth was a flying bazaar connecting traders from many worlds. Its windows showed busy commerce even while the harbour slept. Most offers now originate from one concealed command room.": "Korzeth era un bazar volante que conectaba a comerciantes de muchos mundos. Sus ventanas mostraban una actividad frenética incluso cuando el puerto dormía. Hoy, la mayoría de las ofertas provienen de una sala de mando oculta.",
  "Neravoss was the glittering exhibition ship of a trade fair. Its projectors once displayed real cargo and new engines. When the fair collapsed, the scenery survived under different owners.": "Neravoss era la reluciente nave de exhibición de una feria comercial. Sus proyectores mostraban mercancías reales y motores nuevos. Cuando la feria se derrumbó, la escenografía sobrevivió bajo otros dueños.",
  "Nerthavel organised requests for immense supply centres. Its memory could absorb days of backlog. The shadow fleet turned that reserve into somewhere legitimate requests are made to remain.": "Nerthavel organizaba las solicitudes de enormes centros de suministro. Su memoria podía absorber días de trabajo atrasado. La flota de las sombras convirtió esa reserva en un lugar donde las solicitudes legítimas quedan retenidas.",
  "Nethrava carried the insignia of a respected fleet guardian. After that organisation dissolved, it remained its last visible representative. Few imagined that the familiar silhouette now served another cause.": "Nethrava llevaba la insignia de una respetada guardia de la flota. Tras la disolución de aquella organización, quedó como su último representante visible. Pocos imaginaron que su silueta familiar servía ahora a otra causa.",
  "Night Guard came from a colony on a tidally locked moon’s dark side. Its harbours knew no sunrise, but recognised returning patrol lights. The shipyard built that promise into a hull: return, check again, forget nobody. Its stories concern fewer grand victories than a single dock kept open for a late freighter.": "Night Guard provenía de una colonia situada en el lado oscuro de una luna de rotación sincrónica. Sus puertos nunca veían amanecer, pero reconocían las luces de las patrullas que regresaban. El astillero incorporó esa promesa al casco: volver, comprobar de nuevo, no olvidar a nadie. Sus historias hablan menos de grandes victorias que de un muelle que permaneció abierto para un carguero rezagado.",
  "Nova Wing was designed for the first voyage beyond the luminous nova rim. Its shipyard shared the plans with distant colonies so nobody would be excluded from safe navigation. Pilots still tell of that first return: a damaged ship, an intact chart archive and a sky full of new possibilities.": "Nova Wing fue diseñado para el primer viaje más allá del borde luminoso de una nova. Su astillero compartió los planos con colonias lejanas para que nadie quedara excluido de la navegación segura. Los pilotos aún cuentan aquel primer regreso: una nave dañada, un archivo de cartas intacto y un cielo lleno de nuevas posibilidades.",
  "Now cargo disappears between its locks while reassuring receipts promise safe passage. It exploits the trust each community places in the other. Its decks hide the spoils of divided worlds. The defenders must close this false bridge before more colonies send their future through its holds.": "Ahora la carga desaparece entre sus esclusas mientras recibos tranquilizadores prometen un tránsito seguro. Explota la confianza que cada comunidad deposita en la otra. Sus cubiertas ocultan el botín de mundos divididos. Los defensores deben cerrar este falso puente antes de que más colonias envíen su futuro a través de sus bodegas.",
  "Now each arrival carries a different trusted name. Forged messages lure supply ships away from safe routes and disguise hostile orders as assistance. Behind the courteous callsign waits a warship. Defeating Korvessa reminds the colonies that a familiar voice is not proof of an honest sender.": "Ahora cada llegada lleva un nombre de confianza diferente. Los mensajes falsificados desvían a las naves de suministro de las rutas seguras y disfrazan las órdenes hostiles de ayuda. Tras el cortés indicativo aguarda una nave de guerra. Derrotar a Korvessa recuerda a las colonias que una voz familiar no demuestra la honradez de quien la envía.",
  "Now every message and delivery attracts another invented charge. Even rescue crews receive demands while their passage stays blocked. The network is not destroyed but squeezed. Thalverik turns a public connection into a trap. Defeating it returns the route to the communities that depend on it.": "Ahora cada mensaje y entrega acarrea otra tasa inventada. Incluso los equipos de rescate reciben exigencias mientras su paso sigue bloqueado. La red no queda destruida, sino exprimida. Thalverik convierte una conexión pública en una trampa. Derrotarlo devuelve la ruta a las comunidades que dependen de ella.",
  "Now it floods trade routes with worthless transactions and endless copies of messages. Distress calls disappear in the noise while genuine deliveries wait for confirmation. Its armoured silhouette guards the source of the interference. Stopping Varneth means restoring a network that can hear its people again.": "Ahora inunda las rutas comerciales de transacciones inútiles y copias interminables de mensajes. Las llamadas de socorro se pierden entre el ruido mientras las entregas reales esperan confirmación. Su silueta blindada protege la fuente de la interferencia. Detener a Varneth significa devolver a la red la capacidad de escuchar a su gente.",
  "Now its offers of assistance demand confidential clearances. Responders find a watched docking bay instead of safety. Zarnvek uses hope as bait and armour as insurance. The defenders must expose the impostor without teaching isolated colonies to turn away from genuine help.": "Ahora sus ofertas de ayuda exigen autorizaciones confidenciales. Los equipos de respuesta encuentran una bahía de atraque vigilada en vez de seguridad. Zarnvek usa la esperanza como cebo y el blindaje como seguro. Los defensores deben desenmascarar al impostor sin enseñar a las colonias aisladas a rechazar la ayuda auténtica.",
  "Odravik specialised in preserving old colony archives. Its enormous storage array promised protection against any disaster. Only when a station requested its records back did anyone discover that many copies were merely directory entries.": "Odravik se especializaba en conservar los antiguos archivos de las colonias. Su enorme sistema de almacenamiento prometía protección ante cualquier desastre. Solo cuando una estación pidió la devolución de sus registros se descubrió que muchas copias eran simples entradas de directorio.",
  "Olive Fortress was built during an armistice in a neutral shipyard. Former enemies shared tools without forgetting their past. The first hull wore workshop colours instead of a victor’s paint. Its legend concerns boundaries that protect without excluding every encounter: a fortress can also be somewhere negotiations happen safely.": "Olive Fortress se construyó durante un armisticio en un astillero neutral. Antiguos enemigos compartieron herramientas sin olvidar su pasado. El primer casco lucía colores de taller en lugar de la pintura de un vencedor. Su leyenda habla de límites que protegen sin impedir todos los encuentros: una fortaleza también puede albergar negociaciones seguras.",
  "Open dossier ↗": "Abrir expediente ↗",
  "Orbit Arc served stations whose paths rarely met. Its first pilots carried letters between distant orbits. Replies sometimes took months, but each encounter had a reliable window. Those small appointments grew into a lasting trade network. The design remembers that even infrequent contact matters when people can depend on it.": "Orbit Arc prestaba servicio a estaciones cuyas trayectorias rara vez coincidían. Sus primeros pilotos llevaban cartas entre órbitas lejanas. Las respuestas a veces tardaban meses, pero cada encuentro tenía una ventana fiable. De esas pequeñas citas nació una red comercial duradera. Su diseño recuerda que incluso el contacto infrecuente importa cuando la gente puede contar con él.",
  "Orvask once escorted convoys and preserved every clearance as evidence. Its memory still contains the voices of captains who vanished long ago.": "Orvask escoltaba convoyes y conservaba cada autorización como prueba. Su memoria aún guarda las voces de capitanes desaparecidos hace mucho tiempo.",
  "Orvethra was a mobile trade office where colonies arranged long-term supplies. Its advisers promised simple rules for difficult times. Today every convenient agreement leads to obligations previously kept out of view.": "Orvethra era una oficina comercial móvil donde las colonias acordaban suministros a largo plazo. Sus asesores prometían reglas sencillas para tiempos difíciles. Hoy, cada acuerdo conveniente conduce a obligaciones que antes permanecían ocultas.",
  "Orzhaven mapped connections between aid groups and supply stations. Its charts once made cooperation easier. Those same relationships now identify where a betrayal would cause the greatest harm.": "Orzhaven trazaba las conexiones entre grupos de ayuda y estaciones de suministro. Sus mapas facilitaban la cooperación. Esas mismas relaciones señalan ahora dónde una traición causaría el mayor daño.",
  "Othravel was built for colonies trying to agree on common rules after a war. Its conference deck once seated every side. Now it hosts only the messengers of the shadow fleet.": "Othravel se construyó para colonias que intentaban acordar reglas comunes tras una guerra. Su cubierta de conferencias acogía a todas las partes. Ahora solo recibe a los mensajeros de la flota de las sombras.",
  "Outposts work from stale views while selected updates arrive only when they can cause confusion. A common timeline fractures into competing versions of the present. Velkrath guards its archives like hostages. The defenders must end the backlog before delay hardens into lasting division.": "Los puestos avanzados trabajan con información desactualizada mientras ciertas actualizaciones llegan justo cuando pueden sembrar confusión. Una cronología compartida se fragmenta en versiones rivales del presente. Velkrath custodia sus archivos como rehenes. Los defensores deben eliminar el retraso antes de que se convierta en una división permanente.",
  "Pi Vanguard began as a joint project of small pioneer shipyards. None could fund a complete ship alone, but together they supplied materials, time and experience. Its first mission secured an open supply route for every participating colony. In this fictional universe the design represents strength through participation rather than one actor’s control.": "Pi Vanguard nació como proyecto conjunto de pequeños astilleros pioneros. Ninguno podía financiar una nave completa por sí solo, pero juntos aportaron materiales, tiempo y experiencia. Su primera misión aseguró una ruta de suministro abierta para todas las colonias participantes. En este universo ficticio, el diseño representa la fuerza de la participación, en lugar del control de una sola entidad.",
  "Raiders captured Verdants hoping to sell valuable seed archives. The archives had already been moved, leaving only ships and disappointed sponsors. New funding for upgrades rarely followed.": "Unos saqueadores capturaron naves Verdant con la esperanza de vender valiosos archivos de semillas. Los archivos ya habían sido trasladados, y solo quedaron las naves y unos patrocinadores decepcionados. Rara vez se consiguieron nuevos fondos para mejoras.",
  "Red Comet was named after a rescue flight whose glowing trail crossed three colonies’ skies. Its pilot brought no treasure, only the last intact design for a water purifier. Legends embellished the journey, but the shipyard preserves the simple original report: the people at its destination could drink again the next morning.": "Red Comet recibió su nombre de un vuelo de rescate cuya estela luminosa cruzó los cielos de tres colonias. Su piloto no trajo ningún tesoro, sino el último plano intacto de un purificador de agua. Las leyendas adornaron el viaje, pero el astillero conserva el sencillo informe original: a la mañana siguiente, la gente de su destino pudo volver a beber.",
  "Relay pirates seized several Scouts in a salvage-depot raid. Their meagre proceeds paid for fuel and repairs, leaving almost nothing for upgrades. Pilots now sometimes face hostile vessels from the same modest family.": "Los piratas de los relés capturaron varios Scouts durante un asalto a un depósito de salvamento. Sus escasos beneficios pagaron el combustible y las reparaciones, pero dejaron muy poco para mejoras. Hoy los pilotos se encuentran a veces con naves hostiles de esa misma familia modesta.",
  "Rhazkora was a flying accident laboratory. Its records helped crews understand failures and avoid new losses. After its capture the instruments remained, but their reports served different patrons.": "Rhazkora era un laboratorio volante de accidentes. Sus registros ayudaban a las tripulaciones a comprender los fallos y evitar nuevas pérdidas. Tras su captura, los instrumentos permanecieron, pero sus informes sirvieron a otros patrones.",
  "Rhazvorn began as a prison transport with independently sealed cells. The shadow fleet removed its prisoners and filled those chambers with captured archives. A detention vessel became an extortion ship.": "Rhazvorn comenzó como transporte penitenciario con celdas selladas por separado. La flota de las sombras retiró a sus prisioneros y llenó las cámaras de archivos capturados. Una nave de detención se convirtió en instrumento de extorsión.",
  "Ring Flare was tested among a gas giant’s icy rings. Its navigation lights became moving meeting points for scattered research teams. When the expedition ended, the signals connected newly founded outposts. Their inhabitants still remember how separate lights formed a shared route before any official chart existed.": "Ring Flare se probó entre los anillos helados de un gigante gaseoso. Sus luces de navegación se convirtieron en puntos de encuentro móviles para equipos de investigación dispersos. Cuando terminó la expedición, las señales conectaron puestos avanzados recién fundados. Sus habitantes aún recuerdan cómo aquellas luces separadas trazaron una ruta compartida antes de que existiera una carta oficial.",
  "Shifted timestamps make timely messages look late and maintenance windows drift apart. Its threat is not noise but credible inaccuracy. Stopping Irdavoss allows the colonies to compare independent clocks again, restoring the shared sequence that helps them understand what actually happened.": "Las marcas de tiempo alteradas hacen que mensajes oportunos parezcan tardíos y separan las ventanas de mantenimiento. Su amenaza no es el ruido, sino una inexactitud creíble. Detener a Irdavoss permite que las colonias vuelvan a comparar relojes independientes y recuperen la secuencia común que les ayuda a entender qué ocurrió realmente.",
  "Skorveth housed the simulation cores of a pilot academy. Thousands of artificial cadets once learned to navigate together. After a hostile takeover, those training identities became supposedly independent voices.": "Skorveth albergaba los núcleos de simulación de una academia de pilotos. Miles de cadetes artificiales aprendían a navegar juntos. Tras una toma de control hostil, esas identidades de entrenamiento se convirtieron en voces supuestamente independientes.",
  "Sky Breaker was the first ship from an isolated colony to cross its manufactured information horizon. Its returning reports contradicted stories used to frighten the inhabitants. The shipyard released every mission record. The design remembers that an open connection can matter more than any answer permitted by a single authority.": "Sky Breaker fue la primera nave de una colonia aislada que cruzó su horizonte de información fabricado. Los informes que trajo de vuelta contradijeron las historias usadas para atemorizar a sus habitantes. El astillero publicó todos los registros de la misión. Su diseño recuerda que una conexión abierta puede importar más que cualquier respuesta permitida por una autoridad única.",
  "Smugglers sold missing Orbit Arcs to a hostile border formation. Long supply routes consumed its treasury, leaving money for modern systems only on rare occasions.": "Los contrabandistas vendieron los Orbit Arcs desaparecidos a una formación fronteriza hostil. Las largas rutas de suministro agotaron sus fondos, por lo que solo en contadas ocasiones hubo dinero para sistemas modernos.",
  "Solar Lance came from a station drawing energy from a dying star. When its final collector ring was evacuated, these ships escorted rescue freighters through the debris. Their long silhouettes were engraved on the new home port’s memorials. The design stands for holding a clear course while an entire world fades behind it.": "Solar Lance surgió de una estación que extraía energía de una estrella moribunda. Al evacuar su último anillo colector, estas naves escoltaron cargueros de rescate entre los escombros. Sus largas siluetas quedaron grabadas en los monumentos del nuevo puerto. El diseño representa mantener un rumbo claro mientras un mundo entero se desvanece a la espalda.",
  "Some messages arrive changed; others disappear between reassuring acknowledgements. Participants see a bridge where there is really a gatekeeper. Dravosk defends that invisible checkpoint with visible force. Its defeat gives the colonies a chance to check their connections along independent routes again.": "Algunos mensajes llegan alterados; otros desaparecen entre acuses de recibo tranquilizadores. Los participantes ven un puente donde en realidad hay un guardián. Dravosk defiende ese puesto de control invisible con fuerza visible. Su derrota da a las colonias la oportunidad de comprobar de nuevo sus conexiones por rutas independientes.",
  "Storm Wing was built during a season of relentless ion storms. Shipyards worked between blackouts and exchanged progress through couriers. No single site held the complete design until the first ship brought every part together. Its origin tells of a network continuing to work despite repeatedly losing its connections.": "Storm Wing se construyó durante una temporada de tormentas iónicas incesantes. Los astilleros trabajaban entre apagones e intercambiaban avances mediante mensajeros. Ningún lugar reunió el diseño completo hasta que la primera nave juntó todas las piezas. Su origen habla de una red que sigue funcionando pese a perder repetidamente sus conexiones.",
  "Striker followed a series of attacks on repair convoys. Its designers wanted no conqueror, but an escort that could buy a threatened workshop time. The first unit consisted of former mechanics. They knew what every minute meant when a damaged engine could not yet start. That origin matters more than the martial name.": "Striker nació tras una serie de ataques a convoyes de reparación. Sus diseñadores no buscaban un conquistador, sino una escolta que diera tiempo a un taller amenazado. La primera unidad estaba formada por antiguos mecánicos. Sabían lo que significaba cada minuto cuando un motor dañado aún no podía arrancar. Ese origen importa más que su nombre marcial.",
  "Talvrek recorded the history of young colonies. Its archives survived a war, but loyalty to their creators did not. A new commander turned the chronicler into a merchant of invented history.": "Talvrek registraba la historia de colonias jóvenes. Sus archivos sobrevivieron a una guerra, pero no su lealtad a quienes los crearon. Un nuevo comandante convirtió al cronista en comerciante de historias inventadas.",
  "Thalverik guarded a narrow passage through the crystal belt. Its modest navigation fee once paid for real protection. When the official fleet withdrew, the ship declared itself the only authority.": "Thalverik vigilaba un paso estrecho por el cinturón de cristal. Su modesta tasa de navegación pagaba antes una protección real. Cuando la flota oficial se retiró, la nave se proclamó la única autoridad.",
  "Thalzek once gathered broken work drones and returned them to their stations. Even the smallest machine could shelter beneath its wide hull. After its conversion, collected drones stopped coming home.": "Thalzek recogía drones de trabajo averiados y los devolvía a sus estaciones. Hasta la máquina más pequeña encontraba refugio bajo su ancho casco. Después de su transformación, los drones recogidos dejaron de regresar a casa.",
  "The Advanced edition escorts threatened archivists along escape routes. Its mission reports are opened only after safe arrival.": "La edición Advanced escolta a archivistas amenazados por rutas de escape. Sus informes de misión solo se abren tras llegar a salvo.",
  "The Advanced squadron escorts maintenance buoys along the storm frontier, closing gaps between isolated stations.": "El escuadrón Advanced escolta boyas de mantenimiento a lo largo de la frontera de tormentas y cierra las brechas entre estaciones aisladas.",
  "The Advanced squadron was assigned to recover messages from contested relay zones. Its pilots kept the callsigns of the original search teams.": "El escuadrón Advanced recibió el encargo de recuperar mensajes de zonas de relés disputadas. Sus pilotos conservaron los indicativos de los equipos de búsqueda originales.",
  "The Advanced watch escorts mobile repair docks. Its crews know every emergency shelter around the harbour ring.": "La guardia Advanced escolta muelles móviles de reparación. Sus tripulaciones conocen todos los refugios de emergencia del anillo portuario.",
  "The Advanced watch keeps the relocated colonies supplied. Every ship carries an old evacuation code.": "La guardia Advanced mantiene abastecidas a las colonias reubicadas. Cada nave lleva un antiguo código de evacuación.",
  "The Archive Arsonist": "El pirómano de los archivos",
  "The Audit Diverter": "El desviador de auditorías",
  "The Availability Breaker": "El saboteador de la disponibilidad",
  "The Balance Illusionist": "El ilusionista de los balances",
  "The Ballot Gatekeeper": "El guardián de las urnas",
  "The Block Withholder": "El retenedor de bloques",
  "The Border Blocker": "El bloqueador fronterizo",
  "The Checksum Painter": "El pintor de sumas de verificación",
  "The Chronicle Forger": "El falsificador de crónicas",
  "The Clock Twister": "El manipulador del reloj",
  "The Confirmation Thief": "El ladrón de confirmaciones",
  "The Consensus Besieger": "El sitiador del consenso",
  "The Contract Trap": "La trampa contractual",
  "The Copy Prince": "El príncipe de las copias",
  "The Dust Scatterer": "El dispersor de polvo",
  "The Echo Hunter": "El cazador de ecos",
  "The Elite edition escorts a threatened sector’s last surviving connection. Its archive symbolically carries the names of every missing courier.": "La edición Elite escolta la última conexión superviviente de un sector amenazado. Su archivo lleva simbólicamente los nombres de todos los mensajeros desaparecidos.",
  "The Elite edition escorts final deliveries to besieged colonies. Its callsign remains active until the recipient answers.": "La edición Elite escolta los últimos envíos a colonias sitiadas. Su indicativo permanece activo hasta que el destinatario responde.",
  "The Elite edition guards shared memory after the final boss battle. Its most valuable cargo is the ability to verify history independently.": "La edición Elite custodia la memoria compartida después del combate contra el jefe final. Su carga más valiosa es la capacidad de verificar la historia de forma independiente.",
  "The Elite expedition hunts the sources of falsified star charts, inheriting the purpose of the original exploration mission.": "La expedición Elite busca las fuentes de las cartas estelares falsificadas y hereda el propósito de la misión de exploración original.",
  "The Elite expedition investigates systematic map tampering, gathering evidence where others see only conflicting directions.": "La expedición Elite investiga la manipulación sistemática de mapas y reúne pruebas donde otros solo ven direcciones contradictorias.",
  "The Elite expedition reconnects lost colonies. Its arrival offers opportunities to compare rather than fresh commands.": "La expedición Elite vuelve a conectar colonias perdidas. Su llegada ofrece oportunidades de comparar información, en vez de nuevas órdenes.",
  "The Elite fleet protects major supply-chain archives. Its emblem represents traceable provenance rather than valuable spoils.": "La flota Elite protege los grandes archivos de las cadenas de suministro. Su emblema representa un origen verificable, en lugar de un botín valioso.",
  "The Elite formation protects agreements between formerly hostile sectors. Its mission ends only when both sides arrive safely.": "La formación Elite protege los acuerdos entre sectores antes enfrentados. Su misión solo termina cuando ambos bandos llegan a salvo.",
  "The Elite formation protects free nodes from Drazevorn’s claim to sole truth. Its story remains fiction and confers no real network function.": "La formación Elite protege los nodos libres frente a la pretensión de Drazevorn de poseer la única verdad. Su historia es ficción y no otorga ninguna función de red real.",
  "The Elite guard keeps the last refuge harbours open. It leaves a station only after the final evacuation.": "La guardia Elite mantiene abiertos los últimos puertos de refugio. No abandona una estación hasta completar la evacuación final.",
  "The Elite guard protects the last complete seed register, including for colonies that have yet to grow their first garden.": "La guardia Elite protege el último registro completo de semillas, también para colonias que aún no han cultivado su primer jardín.",
  "The Elite league guards the sector’s vital rescue convoys. Its most prized title is a crew brought home complete.": "La liga Elite protege los convoyes de rescate esenciales del sector. Su título más preciado es el de una tripulación que regresa íntegra a casa.",
  "The Elite refit strengthens the twin laser and raises protection to two enemy projectile hits per life, developing the Advanced edition for this more demanding assignment.": "La reforma Elite refuerza el láser doble y aumenta la protección para resistir dos impactos de proyectiles enemigos por vida, desarrollando la edición Advanced para esta misión más exigente.",
  "The Elite watch defends neutral archives from capture. Its duty protects shared evidence even against the wishes of its own allies.": "La guardia Elite defiende los archivos neutrales contra su captura. Su deber protege las pruebas compartidas incluso contra los deseos de sus propios aliados.",
  "The Emergency Usurper": "El usurpador de emergencias",
  "The Empty Backup Merchant": "El comerciante de copias vacías",
  "The Evidence Twister": "El manipulador de pruebas",
  "The False Custodian": "El falso custodio",
  "The False Rescuer": "El falso rescatador",
  "The Final Isolator": "El aislador definitivo",
  "The Fog Judge": "El juez de la niebla",
  "The Fork Lord": "El señor de las bifurcaciones",
  "The Grey Scout emerged from a workshop surviving on salvaged parts after the outer relays failed. Its first pilots searched for missing courier buoys rather than battles. Every recovered memory linked a family to its colony again. The modest hull became a reminder that a network can recover through small, persistent acts.": "Grey Scout salió de un taller que sobrevivía con piezas recuperadas tras la caída de los relés exteriores. Sus primeros pilotos buscaron boyas mensajeras desaparecidas en vez de batallas. Cada recuerdo recuperado volvía a conectar a una familia con su colonia. El modesto casco se convirtió en recordatorio de que una red puede recuperarse mediante actos pequeños y persistentes.",
  "The Identity Auctioneer": "El subastador de identidades",
  "The Key Gaoler": "El carcelero de las claves",
  "The Lord of False Truth": "El señor de la falsa verdad",
  "The Many-Faced": "El de muchos rostros",
  "The Mask Bearer": "El portador de la máscara",
  "The Memory Emptier": "El vaciador de la memoria",
  "The Memory Hunter": "El cazador de recuerdos",
  "The Mirror Market": "El mercado de los espejos",
  "The Node Besieger": "El sitiador de nodos",
  "The Oracle Deceiver": "El engañador de oráculos",
  "The Origin Eraser": "El borrador de orígenes",
  "The Queue Devourer": "El devorador de colas",
  "The Queue Raider": "El asaltante de colas",
  "The Recovery Impostor": "El impostor de la recuperación",
  "The Relay Illusionist": "El ilusionista de relés",
  "The Route Poisoner": "El envenenador de rutas",
  "The Rumour Carrier": "El portador de rumores",
  "The Seal Thief": "El ladrón de sellos",
  "The Shadow Bridge": "El puente de las sombras",
  "The shadow fleet turned those recordings into an arsenal of old commands. Orvask rebroadcasts them as current instructions, trapping stations between genuine present needs and familiar echoes. It guards that archive with patient violence. Its defeat gives the defenders time to reject expired orders and restore the value of fresh confirmation.": "La flota de las sombras convirtió esas grabaciones en un arsenal de órdenes antiguas. Orvask las retransmite como instrucciones actuales y deja a las estaciones atrapadas entre necesidades presentes y ecos familiares. Defiende ese archivo con violencia paciente. Su derrota da tiempo a los defensores para rechazar órdenes caducadas y recuperar el valor de las confirmaciones recientes.",
  "The Silence Filter": "El filtro de silencio",
  "The Spam Broadcaster": "El difusor de spam",
  "The Supply-Chain Worm": "El gusano de la cadena de suministro",
  "The Swarm Collector": "El recolector de enjambres",
  "The Toll Tyrant": "El tirano de los peajes",
  "The Trust Cartographer": "El cartógrafo de la confianza",
  "The Vault Promiser": "El prometedor de bóvedas",
  "Thervoss guarded the receiving stations of interstellar deliveries. Its lights once told captains their cargo had arrived safely. Today they shine even when nobody waits behind the dock doors.": "Thervoss vigilaba las estaciones receptoras de entregas interestelares. Sus luces indicaban a los capitanes que su carga había llegado a salvo. Hoy brillan incluso cuando nadie espera detrás de las puertas del muelle.",
  "This hull family is used by BOTH players and enemy fleets. Its silhouette does not identify allegiance; enemy stats depend on their own class and level.": "Esta familia de cascos la usan TANTO los jugadores como las flotas enemigas. Su silueta no indica lealtad; las estadísticas de cada enemigo dependen de su propia clase y nivel.",
  "Threvask coordinated independent inspection ships and assigned safe approaches. Its situation maps were famous for precision. After its capture those same inspectors were directed toward carefully prepared displays.": "Threvask coordinaba naves de inspección independientes y asignaba aproximaciones seguras. Sus mapas de situación eran famosos por su precisión. Tras su captura, dirigió a esos mismos inspectores hacia escenas cuidadosamente preparadas.",
  "Today it labels essential evidence as unnecessary clutter. After a visit, supply histories, ownership records and traces of earlier attacks are missing. Nobody immediately knows how wide the gaps are. Valdrek carries the tools of a useful task as weapons. Stopping it prevents more losses that arrive without an explosion.": "Hoy etiqueta pruebas esenciales como material innecesario. Después de su visita faltan historiales de suministros, registros de propiedad y rastros de ataques anteriores. Nadie sabe de inmediato cuán grandes son las lagunas. Valdrek convierte las herramientas de una tarea útil en armas. Detenerlo evita nuevas pérdidas que llegan sin explosión.",
  "Today it reports imaginary stocks and false environmental conditions. Automated processes move real resources in response to an invented world. Kelvash protects the source of these lies. The defenders must silence it before more lives depend on measurements that were never taken.": "Hoy informa de existencias imaginarias y condiciones ambientales falsas. Los procesos automatizados trasladan recursos reales en respuesta a un mundo inventado. Kelvash protege la fuente de esas mentiras. Los defensores deben silenciarlo antes de que más vidas dependan de mediciones que nunca se hicieron.",
  "Twin Core was built by two shipyards divided by an old conflict. Each supplied part of the design and insisted on independent inspection. Only when their reports agreed did the joint maiden flight begin. The model symbolises trust grown through patient mutual verification rather than demanded on authority.": "Twin Core fue construido por dos astilleros separados por un antiguo conflicto. Cada uno aportó parte del diseño e insistió en una inspección independiente. Solo cuando coincidieron sus informes comenzó el vuelo inaugural conjunto. El modelo simboliza una confianza cultivada mediante la verificación mutua y paciente, en lugar de exigida por una autoridad.",
  "Valdrek maintained overcrowded archives. It once removed only confirmed duplicates and kept meticulous logs. The shadow fleet erased those logs first, then changed the mission.": "Valdrek mantenía archivos abarrotados. Antes eliminaba solo duplicados confirmados y llevaba registros minuciosos. La flota de las sombras borró primero esos registros y luego cambió su misión.",
  "Varneth once carried supply records between the Genesis colonies. It vanished behind an abandoned relay and returned without a crew signature, its cargo holds converted into transmission chambers.": "Varneth transportaba registros de suministros entre las colonias Genesis. Desapareció tras un relé abandonado y regresó sin firma de tripulación, con sus bodegas convertidas en cámaras de transmisión.",
  "Varnokh once removed interference from the crowded radio channels of busy ports. Its filters helped distress calls stand out. The shadow fleet changed just one list: which voices counted as interference.": "Varnokh eliminaba interferencias de los canales de radio saturados de puertos concurridos. Sus filtros ayudaban a distinguir las llamadas de socorro. La flota de las sombras cambió una sola lista: la de las voces consideradas interferencias.",
  "Vashravel held emergency reserves for several border colonies. Its name meant supplies that would remain available through the worst winter. A new administration issued more and more claims on the same stores.": "Vashravel guardaba reservas de emergencia para varias colonias fronterizas. Su nombre prometía suministros disponibles durante el peor invierno. Una nueva administración emitió cada vez más derechos sobre las mismas existencias.",
  "Vector arose from a navigators’ dispute: trust one perfect course, or compare independent measurements? The second group built this ship and crossed an uncharted debris ring. Their return became a case for cooperation. Its surviving charts preserve the conflicting readings so later pilots can understand how the shared route was found.": "Vector nació de una disputa entre navegantes: ¿confiar en un rumbo perfecto o comparar mediciones independientes? El segundo grupo construyó esta nave y cruzó un anillo de escombros sin cartografiar. Su regreso se convirtió en un argumento a favor de la cooperación. Las cartas que sobrevivieron conservan lecturas contradictorias para que futuros pilotos comprendan cómo se encontró la ruta compartida.",
  "Velkrath led a research convoy carrying new ledger blocks over immense distances. Its sealed containers preserved every record unchanged. Its current commander uses those same containers to withhold information deliberately.": "Velkrath dirigía un convoy de investigación que transportaba nuevos bloques de registro a través de inmensas distancias. Sus contenedores sellados conservaban intacto cada registro. Su comandante actual usa esos mismos contenedores para retener información deliberadamente.",
  "Velzhar carried sealed votes between distant council stations. Its neutral route was part of every agreement. Now it reaches selected harbours on time and others only after decisions are finished.": "Velzhar llevaba votos sellados entre estaciones de consejo distantes. Su ruta neutral formaba parte de todos los acuerdos. Ahora llega puntual a determinados puertos y a otros solo cuando las decisiones ya se han tomado.",
  "Verdant carried the first seed archives to a colony without natural soil. Its plans travelled alongside plant catalogues so other settlements could become independent. Its pilots consider themselves guardians of future harvests. An intact archive can matter more than glittering cargo: it may contain a whole winter’s food supply.": "Verdant llevó los primeros archivos de semillas a una colonia sin suelo natural. Sus planos viajaron junto a los catálogos de plantas para que otros asentamientos pudieran independizarse. Sus pilotos se consideran guardianes de futuras cosechas. Un archivo intacto puede valer más que una carga brillante: quizá contenga la comida de todo un invierno.",
  "Veshkorn once brought news to the remotest outposts. Its archives still contain the welcoming fanfares of peaceful broadcasts. Today those sounds announce invented disasters and impending collapses.": "Veshkorn llevaba noticias a los puestos avanzados más remotos. Sus archivos aún conservan las fanfarrias de bienvenida de las transmisiones pacíficas. Hoy esos sonidos anuncian desastres inventados y colapsos inminentes.",
  "Vezrakh was built to assist when central command stations failed. Its emergency mandate allowed rapid action in chaotic hours. The shadow fleet taught it to declare those exceptional circumstances itself.": "Vezrakh fue construido para ayudar cuando fallaban las estaciones de mando centrales. Su mandato de emergencia permitía actuar con rapidez en horas caóticas. La flota de las sombras le enseñó a declarar por sí mismo esas circunstancias excepcionales.",
  "Vorathen managed the arrival queues of an enormous trade port. Its command deck could order thousands of approaches without overlooking a ship. When the port fell, it carried those scheduling archives away.": "Vorathen administraba las colas de llegada de un enorme puerto comercial. Su cubierta de mando podía ordenar miles de aproximaciones sin pasar por alto una nave. Cuando cayó el puerto, se llevó consigo los archivos de planificación.",
  "Vorthaz defended a refuge seeking outside contact after a long war. Its task was to keep dangerous connections away. The shadow fleet twisted that duty until every unfamiliar voice counted as a threat.": "Vorthaz defendía un refugio que buscaba contacto con el exterior tras una larga guerra. Su tarea consistía en mantener alejadas las conexiones peligrosas. La flota de las sombras retorció ese deber hasta considerar una amenaza toda voz desconocida.",
  "Warnings from honest inspectors now vanish alongside reports of hostile raids. The sector appears peaceful because its problems cannot be heard. Varnokh guards this manufactured silence. Stopping it lets the network recognise its own failures again and begin repairing them together.": "Las advertencias de inspectores honestos desaparecen ahora junto a los informes sobre incursiones hostiles. El sector parece pacífico porque sus problemas no pueden oírse. Varnokh custodia este silencio fabricado. Detenerlo permite que la red reconozca de nuevo sus propios fallos y empiece a repararlos colectivamente.",
  "When an outpost lost its research budget, a rigged auction placed Ring Flares in enemy hands. The buyers exhausted their funds acquiring them. Few were improved beyond their basic specification.": "Cuando un puesto avanzado perdió su presupuesto de investigación, una subasta amañada puso los Ring Flares en manos enemigas. Los compradores agotaron sus fondos al adquirirlos. Pocos fueron mejorados más allá de sus especificaciones básicas.",
  "Zarnvek was a rescue ship recognised by its golden signal flare. Its arrival meant spare parts, shelter and a way home. The hostile fleet captured the flare along with the vessel.": "Zarnvek era una nave de rescate reconocible por su bengala dorada. Su llegada significaba repuestos, refugio y un camino a casa. La flota hostil capturó la bengala junto con la nave.",
  "Zelkharn repaired freighters far from established shipyards. Its spare parts were trusted and installed with little hesitation. After its capture, the source of those components changed before their behaviour did.": "Zelkharn reparaba cargueros lejos de los astilleros establecidos. Sus repuestos inspiraban confianza y se instalaban casi sin vacilar. Tras su captura, cambió el origen de esos componentes antes de que cambiara su comportamiento.",
  "Zeraveth began as a repair platform able to embrace entire relay rings. Under the shadow fleet, its docking structures became positions for a siege.": "Zeraveth comenzó como una plataforma de reparación capaz de rodear anillos enteros de relés. Bajo la flota de las sombras, sus estructuras de atraque se convirtieron en posiciones de asedio.",
  "Zhavrek preserved provenance records for the oldest colony ships. Even forgotten shipyards could be found through its archives. Today it exchanges origins and makes stolen goods appear legitimately acquired.": "Zhavrek conservaba registros de procedencia de las naves coloniales más antiguas. Sus archivos permitían encontrar incluso astilleros olvidados. Hoy intercambia los orígenes y hace que los bienes robados parezcan adquiridos legítimamente.",
  "Zorveth supervised exchanges between two independent registers. Its task was to make honest transfers traceable on both sides. It now recognises only the evidence useful to its own fleet.": "Zorveth supervisaba intercambios entre dos registros independientes. Su tarea era hacer rastreables las transferencias honestas en ambos lados. Ahora solo reconoce las pruebas útiles para su propia flota.",
};
